template<class T>std::vector<T> Read(const fs::path& path,size_t count){Need(fs::file_size(path)==count*sizeof(T),"Fixture byte extent differs");std::vector<T> v(count);std::ifstream f(path,std::ios::binary);f.read(reinterpret_cast<char*>(v.data()),v.size()*sizeof(T));Need(bool(f),"Cannot read fixture");return v;}
