int main(int argc,char**argv){try{@autoreleasepool{
 Need(argc==4,"ARCHIVE_DIRECTORY FROZEN_CAPTURE_ROOT NEW_OUTPUT");fs::path archives=fs::absolute(argv[1]),captures=fs::absolute(argv[2]),output=fs::absolute(argv[3]);Need(fs::create_directory(output),"Output must be new");NSError* error=nil;auto device=MTLCreateSystemDefaultDevice();Need(device!=nil&&[device supportsFamily:MTLGPUFamilyApple10],"Expected qualified device");auto queue=[device newCommandQueue];Need(queue!=nil,"No queue");
 NSString* text=[NSString stringWithContentsOfFile:[NSString stringWithUTF8String:(archives/"runtime-source.metal").c_str()] encoding:NSUTF8StringEncoding error:&error];Check(text!=nil,error,"Load exact shader source");auto options=[MTLCompileOptions new];options.languageVersion=MTLLanguageVersion4_0;options.mathMode=MTLMathModeSafe;auto library=[device newLibraryWithSource:text options:options error:&error];Check(library!=nil,error,"Recreate source library");auto gather=[device newComputePipelineStateWithFunction:[library newFunctionWithName:@"packed_affine_gather"] error:&error];Check(gather!=nil,error,"Compile unchanged gather");
 auto guard=[device newComputePipelineStateWithFunction:[library newFunctionWithName:@"packed_affine_layout_guard"] error:&error];Check(guard!=nil,error,"Compile same-library ABI guard");auto status=[device newBufferWithLength:128 options:MTLResourceStorageModeShared];Need(status!=nil,"Guard allocation");std::fill_n(static_cast<uint32_t*>(status.contents),32,UINT32_MAX);auto command=[queue commandBuffer];auto encoder=[command computeCommandEncoder];Need(command&&encoder,"Guard command allocation");[encoder setComputePipelineState:guard];[encoder setBuffer:status offset:0 atIndex:0];[encoder dispatchThreadgroups:MTLSizeMake(1,1,1) threadsPerThreadgroup:MTLSizeMake(32,1,1)];[encoder endEncoding];[command commit];[command waitUntilCompleted];Need(command.status==MTLCommandBufferStatusCompleted&&Garnet::PackedAffineLayoutMatches(static_cast<uint32_t*>(status.contents),32),"Cooperative ABI differs");
 std::array<Fixture,3> fixtures;const std::array<const char*,3> folders{"capture-up2","capture-down1","capture-qo1"};const std::array<size_t,3> ns{14336,4096,4096},ks{4096,14336,4096};const size_t m=512;std::array<uint32_t,512> indices;for(size_t i=0;i<m;++i)indices[i]=uint32_t(i);
 for(size_t f=0;f<3;++f){auto& v=fixtures[f];v.n=ns[f];v.k=ks[f];v.source=captures/folders[f];v.input=Read<float>(v.source/"input-parent.f32",514*v.k);v.reference=Read<float>(v.source/"reference-parent.f32",514*v.n);v.weights=Read<uint32_t>(v.source/"weight.u32",v.n*v.k/8);v.scales=Read<uint16_t>(v.source/"scales.f16",v.n*v.k/64);v.biases=Read<uint16_t>(v.source/"biases.f16",v.n*v.k/64);v.poison.assign(v.reference.size(),std::numeric_limits<float>::quiet_NaN());std::copy_n(v.reference.begin(),v.n,v.poison.begin());std::copy(v.reference.end()-v.n,v.reference.end(),v.poison.end()-v.n);
  auto upload=[&](const auto& data){auto buffer=[device newBufferWithBytes:data.data() length:data.size()*sizeof(data[0]) options:MTLResourceStorageModeShared];Need(buffer!=nil,"Fixture upload failed");return buffer;};v.a=upload(v.input);v.w=upload(v.weights);v.s=upload(v.scales);v.b=upload(v.biases);v.o=upload(v.poison);v.compact=[device newBufferWithLength:14680064 options:MTLResourceStorageModeShared];Need(v.compact!=nil,"Compact scratch allocation");
  for(size_t tile:{size_t(128),size_t(256)}){auto constants=[MTLFunctionConstantValues new];const uint32_t dims[]{uint32_t(v.k),uint32_t(v.n),uint32_t(v.k),uint32_t(v.n)};for(NSUInteger i=0;i<4;++i)[constants setConstantValue:dims+i type:MTLDataTypeUInt atIndex:10+i];NSString* name=tile==128?@"half_m128k128":@"half_m256k128";auto function=[library newFunctionWithName:name constantValues:constants error:&error];Check(function!=nil,error,"Specialize same original source");NSString* file=[NSString stringWithFormat:@"%@-K%zu-N%zu.metalar",name,v.k,v.n];auto ad=[MTLBinaryArchiveDescriptor new];ad.url=[NSURL fileURLWithPath:[[NSString stringWithUTF8String:archives.c_str()] stringByAppendingPathComponent:file]];auto archive=[device newBinaryArchiveWithDescriptor:ad error:&error];Check(archive!=nil,error,"Load original archive");auto pd=[MTLComputePipelineDescriptor new];pd.computeFunction=function;pd.binaryArchives=@[archive];auto pipeline=[device newComputePipelineStateWithDescriptor:pd options:MTLPipelineOptionFailOnBinaryArchiveMiss reflection:nil error:&error];Check(pipeline!=nil,error,"Original archive lookup failed");Need(pipeline.threadExecutionWidth==32&&pipeline.maxTotalThreadsPerThreadgroup>=256&&pipeline.staticThreadgroupMemoryLength==17408,"Pipeline resources changed");v.pso[tile==256]=pipeline;}
 }
 JSON cells=JSON::array();uint64_t observations=0;
 auto execute=[&](Fixture& v,size_t tile,bool keep){@autoreleasepool{
  std::memcpy(v.o.contents,v.poison.data(),v.poison.size()*4);auto cb=[queue commandBuffer];auto e=[cb computeCommandEncoder];Need(cb&&e,"Cannot encode gather");const uint32_t shape[]{uint32_t(m),uint32_t(v.k),uint32_t(v.k),0};[e setComputePipelineState:gather];[e setBuffer:v.a offset:v.k*4 atIndex:0];[e setBuffer:v.compact offset:0 atIndex:1];[e setBytes:indices.data() length:sizeof(indices) atIndex:2];[e setBytes:shape length:sizeof(shape) atIndex:3];[e dispatchThreads:MTLSizeMake(m*v.k,1,1) threadsPerThreadgroup:MTLSizeMake(256,1,1)];[e endEncoding];
  e=[cb computeCommandEncoder];Need(e!=nil,"Cannot encode original product");struct Params {uint64_t rows,inner,columns,aStride,oStride;};const Params p{m,v.k,v.n,v.k,v.n};[e setComputePipelineState:v.pso[tile==256]];[e setBuffer:v.compact offset:0 atIndex:0];[e setBuffer:v.w offset:0 atIndex:1];[e setBuffer:v.s offset:0 atIndex:2];[e setBuffer:v.b offset:0 atIndex:3];[e setBuffer:v.o offset:v.n*4 atIndex:4];[e setBytes:&p length:sizeof(p) atIndex:5];[e setBytes:indices.data() length:sizeof(indices) atIndex:6];[e dispatchThreadgroups:MTLSizeMake(v.n/64,(m+tile-1)/tile,1) threadsPerThreadgroup:MTLSizeMake(256,1,1)];[e endEncoding];[cb commit];[cb waitUntilCompleted];Need(cb.status==MTLCommandBufferStatusCompleted,"Original product failed");double ms=1000*(cb.GPUEndTime-cb.GPUStartTime);Need(std::isfinite(ms)&&ms>0,"Invalid native GPU envelope");
  // The timing span ends above. All CPU comparisons/readback/saves follow it.
