  if(keep){std::vector<float> actual(v.reference.size());std::memcpy(actual.data(),v.o.contents,actual.size()*4);Save(output/(std::string(tile==128?"M128":"M256")+"-K"+std::to_string(v.k)+"-N"+std::to_string(v.n)+"-parent.f32"),actual);}
  return ms;
 }};
 for(size_t f=0;f<3;++f){auto& v=fixtures[f];for(size_t warm=0;warm<3;++warm){execute(v,128,false);execute(v,256,false);}JSON samples=JSON::array();for(size_t round=0;round<9;++round)for(size_t order=0;order<2;++order){size_t tile=((round+order)%2)?256:128;double ms=execute(v,tile,round==8);samples.push_back({{"round",round},{"order",order},{"tile",tile},{"gpu_ms_inclusive_gather",ms}});}cells.push_back({{"M",m},{"N",v.n},{"K",v.k},{"source",v.source.string()},{"original_selected_tile",v.n==14336||v.k==14336?256:128},{"samples",samples}});}
 JSON report={{"completed",true},{"scope","Three512-row frozen-fixture component screens of two existing original kernels via validated binary archives. Includes identical actual gather; no model, serving, occupancy, stall, new math, or general precision claim."},{"device",std::string(device.name.UTF8String)},{"registry_id",device.registryID},{"math_mode","Safe"},{"warmups_per_tile",3},{"measurements_per_tile",9},{"arithmetic_dispatches",72},{"cooperative_abi_guard_passed",true},{"all_parent_outputs_and_guards_exact",true},{"read_only_inputs_exact",true},{"logical_output_observations",observations},{"cells",cells}};std::ofstream stream(output/"result.json");stream<<report.dump(2)<<"\n";Need(bool(stream),"Cannot save report");std::cout<<"Existing archived tile screen PASS; logical output observations="<<observations<<"\n";return 0;
